import{_ as e,o,c as n,a2 as a}from"./chunks/framework.mRCPFc5l.js";const w=JSON.parse('{"title":"Statement downloader","description":"","frontmatter":{"title":"Statement downloader"},"headers":[],"relativePath":"docs/tools/statement-downloader.md","filePath":"docs/tools/statement-downloader.md","lastUpdated":1790449305000}'),s={name:"docs/tools/statement-downloader.md"};function r(i,t,d,l,h,u){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="statement-downloader" tabindex="-1">Statement downloader <a class="header-anchor" href="#statement-downloader" aria-label="Permalink to &quot;Statement downloader&quot;">​</a></h1><p>Instead of manually logging into your bank&#39;s website and downloading statements one by one, the Statement Downloader can do it for you, for supported institutions.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li><strong>Launch browser</strong> — OrbySystems opens a browser window for you.</li><li><strong>Log in and navigate</strong> — you log in on the real bank site yourself (OrbySystems never sees or stores your credentials) and go to the statements page.</li><li><strong>Scan</strong> — OrbySystems highlights the statement links it recognizes on the page.</li></ol><p>From there, choose the account and year(s) you want, and download. Files are saved to a per-institution folder shown in the tool, which you can change.</p><h2 id="adding-support-for-a-new-institution" tabindex="-1">Adding support for a new institution <a class="header-anchor" href="#adding-support-for-a-new-institution" aria-label="Permalink to &quot;Adding support for a new institution&quot;">​</a></h2><p>Only supported institutions can be scanned. If yours isn&#39;t recognized yet, see the <a href="/docs/tools/statement-downloader-builder">Statement Downloader Builder</a>.</p>',7)])])}const p=e(s,[["render",r]]);export{w as __pageData,p as default};
